-- Backend Engineering ("The Fracture") post-game content -- "Messaging Mastery" world.
-- Opens Arc IX -- Mastery. 1 campaign, 2 operations, 12 missions (11 lessons + boss),
-- following the same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every prior Act. The world row itself already exists
-- (spine migration 20260810420000_backend_postgame_spine.sql) -- this migration only
-- adds mission content underneath it. The Fracture mystery is resolved; this module is
-- pure post-game skill mastery, no ongoing incident thread.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be-messaging-mastery', 'world-be-messaging-mastery', 'messaging-mastery', 'Mastery A - Messaging Systems', 'The Fracture is closed. What''s left is the page leadership actually asked for: which of Forge''s four options -- a synchronous API, BullMQ, RabbitMQ, or Kafka -- is correct for a given job, and why the other three would have been wrong.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be-messaging-mastery-1', 'campaign-be-messaging-mastery', 'queues-and-brokers', 'Queues and Brokers', 'BullMQ and RabbitMQ, taken apart and put back together: the backing store, the delivery guarantees, and the failure modes that only show up under real load.', 1),
  ('operation-be-messaging-mastery-2', 'campaign-be-messaging-mastery', 'streams-and-judgment', 'Streams and Judgment', 'Kafka''s deeper internals, its ecosystem, and the judgment calls -- system by system, scenario by scenario -- that the whole module has been building toward.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-messaging-mastery-01', 'world-be-messaging-mastery', 'campaign-be-messaging-mastery', 'operation-be-messaging-mastery-1', 'bullmq-internals', 'BullMQ Internals', 'BullMQ isn''t a message broker at all -- it''s a set of very disciplined data structures living inside Redis. Start where the jobs actually live.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"bullmq-internals-sim"}'::jsonb, '{"xp":382,"credits":74}'::jsonb, false, 1),
  ('mission-be-messaging-mastery-02', 'world-be-messaging-mastery', 'campaign-be-messaging-mastery', 'operation-be-messaging-mastery-1', 'bullmq-reliability', 'BullMQ Reliability', 'Delayed jobs, repeatable jobs, retries with backoff, concurrency, rate limiting, and flows of parent and child jobs -- the features that turn a job queue into something you can actually trust in production.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-messaging-mastery-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"bullmq-reliability-sim"}'::jsonb, '{"xp":384,"credits":74}'::jsonb, false, 2),
  ('mission-be-messaging-mastery-03', 'world-be-messaging-mastery', 'campaign-be-messaging-mastery', 'operation-be-messaging-mastery-1', 'rabbitmq-deep-dive-i', 'RabbitMQ Deep Dive I', 'A queue is not where routing happens -- an exchange is. Direct, topic, fanout and headers exchanges each answer "who gets this message" a different way.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-messaging-mastery-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"rabbitmq-deep-dive-i-sim"}'::jsonb, '{"xp":386,"credits":75}'::jsonb, false, 3),
  ('mission-be-messaging-mastery-04', 'world-be-messaging-mastery', 'campaign-be-messaging-mastery', 'operation-be-messaging-mastery-1', 'rabbitmq-deep-dive-ii', 'RabbitMQ Deep Dive II', 'Acknowledgements, prefetch, durability, dead-letter exchanges, publisher confirms -- the mechanics that decide whether a RabbitMQ message actually survives a crash, and where it goes when a consumer keeps rejecting it.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-messaging-mastery-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"rabbitmq-deep-dive-ii-sim"}'::jsonb, '{"xp":388,"credits":75}'::jsonb, false, 4),
  ('mission-be-messaging-mastery-05', 'world-be-messaging-mastery', 'campaign-be-messaging-mastery', 'operation-be-messaging-mastery-1', 'kafka-internals-i', 'Kafka Internals I', 'Past the basics: leaders, followers, in-sync replicas, and the replication factor that decides how many machines can vanish before a partition actually goes down.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-messaging-mastery-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"kafka-internals-i-sim"}'::jsonb, '{"xp":390,"credits":75}'::jsonb, false, 5),
  ('mission-be-messaging-mastery-06', 'world-be-messaging-mastery', 'campaign-be-messaging-mastery', 'operation-be-messaging-mastery-1', 'kafka-internals-ii', 'Kafka Internals II', 'Consumer groups don''t just split work -- how that work gets split, and how badly a rebalance disrupts everyone while it happens, comes down to which assignment strategy is actually running.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-messaging-mastery-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"kafka-internals-ii-sim"}'::jsonb, '{"xp":392,"credits":76}'::jsonb, false, 6);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-messaging-mastery-07', 'world-be-messaging-mastery', 'campaign-be-messaging-mastery', 'operation-be-messaging-mastery-2', 'kafka-internals-iii', 'Kafka Internals III', 'How long a log lives, what log compaction actually keeps, and the two features -- idempotent producers and transactions -- that let Kafka promise a message was written exactly once.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-messaging-mastery-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"kafka-internals-iii-sim"}'::jsonb, '{"xp":394,"credits":76}'::jsonb, false, 7),
  ('mission-be-messaging-mastery-08', 'world-be-messaging-mastery', 'campaign-be-messaging-mastery', 'operation-be-messaging-mastery-2', 'kafka-ecosystem', 'Kafka Ecosystem', 'Kafka alone is a log. Schema registry, Kafka Connect, and stream processing are what turn that log into an actual data platform -- and each one has its own way of breaking.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-messaging-mastery-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"kafka-ecosystem-sim"}'::jsonb, '{"xp":396,"credits":76}'::jsonb, false, 8),
  ('mission-be-messaging-mastery-09', 'world-be-messaging-mastery', 'campaign-be-messaging-mastery', 'operation-be-messaging-mastery-2', 'choosing-your-tool-i', 'Choosing Your Tool I', 'A synchronous API, BullMQ, or a plain database job table -- three ways to do work that doesn''t have to happen this millisecond, and only one of them is right for any given case.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-messaging-mastery-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"choosing-your-tool-i-sim"}'::jsonb, '{"xp":398,"credits":77}'::jsonb, false, 9),
  ('mission-be-messaging-mastery-10', 'world-be-messaging-mastery', 'campaign-be-messaging-mastery', 'operation-be-messaging-mastery-2', 'choosing-your-tool-ii', 'Choosing Your Tool II', 'RabbitMQ, Kafka, WebSocket, or SSE -- four ways to move something from one place to another, and picking by familiarity instead of fit is exactly how three past incidents happened.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-messaging-mastery-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"choosing-your-tool-ii-sim"}'::jsonb, '{"xp":400,"credits":77}'::jsonb, false, 10),
  ('mission-be-messaging-mastery-11', 'world-be-messaging-mastery', 'campaign-be-messaging-mastery', 'operation-be-messaging-mastery-2', 'the-warm-up-scenarios', 'The Warm-Up Scenarios', 'Before the real trial: a handful of scenarios, judged the same way leadership''s decision page will have to be judged. Get comfortable being right for the right reason.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-messaging-mastery-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"warm-up-scenarios-sim"}'::jsonb, '{"xp":402,"credits":77}'::jsonb, false, 11),
  ('mission-be-messaging-mastery-12', 'world-be-messaging-mastery', 'campaign-be-messaging-mastery', 'operation-be-messaging-mastery-2', 'the-trial-of-twenty-scenarios', 'The Trial of Twenty Scenarios', 'The page leadership actually asked for. Given a scenario, name the correct system -- and be ready to say exactly why the other three were wrong for it.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-messaging-mastery-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"trial-of-twenty-scenarios-boss-sim"}'::jsonb, '{"xp":780,"credits":190,"badgeIds":["trial-of-twenty-scenarios"],"skillXp":{"messaging_mastery":35}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be-messaging-mastery-01', 1, 'mira', 'The Fracture''s closed, the postmortems are filed, and for once nobody''s paging us. Good time to actually master the tools we reached for under pressure instead of just barely surviving them.'),
  ('mission-be-messaging-mastery-01', 2, 'forge', 'Starting with BullMQ, since half of Forge Division''s background jobs already run on it. First correction: BullMQ is not a broker. It''s a job queue built entirely out of Redis data structures -- sorted sets for delays, lists for the ready queue, hashes for job data.'),
  ('mission-be-messaging-mastery-01', 3, 'mira', 'Everything BullMQ promises -- ordering, atomicity, persistence across a crash -- it''s promising because of what Redis itself guarantees. Understand the storage and the API stops feeling like magic.'),

  ('mission-be-messaging-mastery-02', 1, 'forge', 'BullMQ''s reliability features aren''t decoration -- delayed jobs, repeatable jobs, retries with backoff, concurrency limits, rate limiting, and flows for parent/child jobs are the actual reasons production teams trust it with real work.'),
  ('mission-be-messaging-mastery-02', 2, 'mira', 'Every one of them is a knob. Leave it at the default without understanding what it trades off, and you''ll find out the hard way -- usually at 2am, usually with a queue backed up past anyone''s patience.'),

  ('mission-be-messaging-mastery-03', 1, 'mira', 'RabbitMQ''s actual model surprises people who''ve only used it casually: a producer never sends a message to a queue. It sends it to an exchange, and the exchange decides where it goes.'),
  ('mission-be-messaging-mastery-03', 2, 'forge', 'Four exchange types, four different routing philosophies. Direct matches an exact routing key. Topic matches a pattern. Fanout ignores the key entirely and broadcasts. Headers routes on message attributes instead of the key at all.'),
  ('mission-be-messaging-mastery-03', 3, 'mira', 'Get the exchange type wrong for what you actually need and messages don''t error out -- they just quietly never arrive anywhere. That''s the failure mode to watch for.'),

  ('mission-be-messaging-mastery-04', 1, 'forge', 'Past routing: what actually happens to a message once it''s in a queue. Acknowledgements, prefetch count, durability flags, publisher confirms, and dead-letter exchanges -- the mechanics that decide whether a crash loses a message or just delays it.'),
  ('mission-be-messaging-mastery-04', 2, 'mira', 'Auto-ack is the one that gets people. It feels like a convenience setting. It''s actually a promise that you don''t care whether the consumer finishes before it dies.'),

  ('mission-be-messaging-mastery-05', 1, 'mira', 'Kafka''s basics are old news to this team by now. What we skipped, under incident pressure, was replication: leaders, followers, and the in-sync replica set that decides what "durable" actually means.'),
  ('mission-be-messaging-mastery-05', 2, 'forge', 'Every partition has one leader handling all reads and writes, and zero or more followers replicating it. "In-sync" isn''t automatic -- a follower that falls too far behind gets dropped from the ISR, quietly, and stops counting toward durability.'),

  ('mission-be-messaging-mastery-06', 1, 'forge', 'Consumer groups split partitions across instances -- we covered that. What we didn''t cover is how: the partition assignment strategy decides who ends up with what, and it''s not the same algorithm every time.'),
  ('mission-be-messaging-mastery-06', 2, 'mira', 'Range, round-robin, sticky, cooperative-sticky -- and the difference between the old eager rebalance and the newer incremental one is the difference between "everyone stops" and "only the moving partitions stop."'),

  ('mission-be-messaging-mastery-07', 1, 'mira', 'Three more pieces of the log we glossed over during the incident: how long it actually lives, what log compaction keeps instead of deleting, and how Kafka manages to promise a message was written exactly once.'),
  ('mission-be-messaging-mastery-07', 2, 'forge', 'Retention deletes by age or size. Compaction is different -- it keeps only the latest value per key, forever, which is a completely different retention philosophy hiding under the same word.'),
  ('mission-be-messaging-mastery-07', 3, 'mira', 'And idempotent producers plus transactions are what get you from "at least once" to "exactly once," for real, not just in the settings panel.'),

  ('mission-be-messaging-mastery-08', 1, 'forge', 'Kafka on its own is just a log. Schema registry, Kafka Connect, and stream processing are the ecosystem that turns that log into something teams actually build a platform on.'),
  ('mission-be-messaging-mastery-08', 2, 'mira', 'Each one solves a real problem -- schema drift, connecting to external systems without writing bespoke code, computing over the stream instead of just storing it. Each one also has its own way of quietly breaking.'),

  ('mission-be-messaging-mastery-09', 1, 'mira', 'Here''s the page leadership actually wants, built one decision at a time. First split: work that doesn''t have to happen right now. Synchronous API, BullMQ, or a plain database table with a status column -- when is each one actually correct?'),
  ('mission-be-messaging-mastery-09', 2, 'forge', 'This is the comparison teams get wrong constantly, usually by defaulting to whichever one they already have running somewhere.'),

  ('mission-be-messaging-mastery-10', 1, 'forge', 'Second split: moving something from one place to another. RabbitMQ, Kafka, WebSocket, SSE -- four tools, four very different jobs, and "they all involve sending messages" is not a reason to treat them as interchangeable.'),
  ('mission-be-messaging-mastery-10', 2, 'mira', 'Three of the incidents in our own history happened because someone reached for the familiar tool instead of the correct one. We''re naming all three before this module is done.'),

  ('mission-be-messaging-mastery-11', 1, 'mira', 'Before the real trial: warm up. A handful of scenarios, same judgment call each time -- which system, and why not the other three.'),
  ('mission-be-messaging-mastery-11', 2, 'forge', 'No trick questions. Just the same discipline, repeated until it''s automatic.'),

  ('mission-be-messaging-mastery-12', 1, 'mira', 'This is it -- the page leadership asked for, for real this time. Twenty scenarios came in from every team in the building. I''ve pulled a representative handful.'),
  ('mission-be-messaging-mastery-12', 2, 'forge', 'Same rule as always: name the correct system, and be ready to say exactly why the other three are wrong for this specific case. Familiarity doesn''t count as a reason.'),
  ('mission-be-messaging-mastery-12', 3, 'mira', 'One more thing while you work through these. Compiling twenty scenarios meant pulling logs across every messaging system we run -- and three separate ones still show that doubled-slash pattern in a resource path. Different systems, same artifact.'),
  ('mission-be-messaging-mastery-12', 4, 'forge', 'Filed, same as always. It''s never once caused an incident on its own. I still don''t like how consistently it shows up.'),
  ('mission-be-messaging-mastery-12', 5, 'mira', 'Noted, and same answer as always -- it''s not today''s problem. Today''s problem is these twenty scenarios. Let''s close it out.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be-messaging-mastery-01-o1', 'mission-be-messaging-mastery-01', 1, 'Explain BullMQ''s Redis foundation', 'Choose the reason BullMQ can promise atomic, ordered job handoffs without running its own storage engine.'),
  ('mission-be-messaging-mastery-01-o2', 'mission-be-messaging-mastery-01', 2, 'Match the BullMQ building blocks', 'Match each BullMQ class to the role it actually plays.'),
  ('mission-be-messaging-mastery-02-o1', 'mission-be-messaging-mastery-02', 1, 'Match the reliability feature to what it solves', 'Match each BullMQ reliability feature to the problem it actually solves.'),
  ('mission-be-messaging-mastery-02-o2', 'mission-be-messaging-mastery-02', 2, 'Find the retry bug', 'Debug a retry configuration that hammers a downstream outage instead of backing off.'),
  ('mission-be-messaging-mastery-03-o1', 'mission-be-messaging-mastery-03', 1, 'Match the exchange type to its routing behavior', 'Match each RabbitMQ exchange type to how it actually routes messages.'),
  ('mission-be-messaging-mastery-03-o2', 'mission-be-messaging-mastery-03', 2, 'Diagnose the missing binding', 'Find the evidence that explains why a published message never reaches a queue that should have received it.'),
  ('mission-be-messaging-mastery-04-o1', 'mission-be-messaging-mastery-04', 1, 'Find the acknowledgement bug', 'Debug a consumer configuration that loses a message outright whenever it crashes mid-processing.'),
  ('mission-be-messaging-mastery-04-o2', 'mission-be-messaging-mastery-04', 2, 'Design the dead-letter path', 'Choose the fix for a poison message that blocks every message behind it forever.'),
  ('mission-be-messaging-mastery-05-o1', 'mission-be-messaging-mastery-05', 1, 'Match the replication piece to its role', 'Match each Kafka replication concept to what it actually does.'),
  ('mission-be-messaging-mastery-05-o2', 'mission-be-messaging-mastery-05', 2, 'Diagnose the under-replicated partition', 'Find the evidence that explains why a partition is one leader failure away from data loss despite a healthy cluster.'),
  ('mission-be-messaging-mastery-06-o1', 'mission-be-messaging-mastery-06', 1, 'Match the assignment strategy to its behavior', 'Match each partition assignment strategy to how it actually behaves during a rebalance.'),
  ('mission-be-messaging-mastery-06-o2', 'mission-be-messaging-mastery-06', 2, 'Diagnose the rebalance stall', 'Find the evidence that explains why one consumer restarting stopped an entire group of twelve.'),
  ('mission-be-messaging-mastery-07-o1', 'mission-be-messaging-mastery-07', 1, 'Match the mechanism to what it guarantees', 'Match each Kafka mechanism to the guarantee it actually provides.'),
  ('mission-be-messaging-mastery-07-o2', 'mission-be-messaging-mastery-07', 2, 'Diagnose the compacted topic surprise', 'Find the evidence that explains why a new consumer got only the latest value per key instead of full history.'),
  ('mission-be-messaging-mastery-08-o1', 'mission-be-messaging-mastery-08', 1, 'Match the ecosystem tool to its job', 'Match each Kafka ecosystem tool to the problem it actually solves.'),
  ('mission-be-messaging-mastery-08-o2', 'mission-be-messaging-mastery-08', 2, 'Diagnose the schema break', 'Find the evidence that explains why a producer deploy was rejected before a single message reached the topic.'),
  ('mission-be-messaging-mastery-09-o1', 'mission-be-messaging-mastery-09', 1, 'Scenario: order confirmation email', 'Choose the correct tool for work that must not block the response but should run within seconds.'),
  ('mission-be-messaging-mastery-09-o2', 'mission-be-messaging-mastery-09', 2, 'Scenario: nightly report generation', 'Choose the correct tool for infrequent, exactly-once-per-run work with no new infrastructure available.'),
  ('mission-be-messaging-mastery-10-o1', 'mission-be-messaging-mastery-10', 1, 'Scenario: order events fanning out to five services', 'Choose the correct tool for one event needing independent replay by an unknown number of future consumers.'),
  ('mission-be-messaging-mastery-10-o2', 'mission-be-messaging-mastery-10', 2, 'Scenario: live delivery-driver location on a dashboard', 'Choose the correct tool for high-fanout, one-way, near-real-time updates to a browser.'),
  ('mission-be-messaging-mastery-11-o1', 'mission-be-messaging-mastery-11', 1, 'Scenario: password reset token', 'Choose the correct tool for a non-blocking email send that should happen within seconds.'),
  ('mission-be-messaging-mastery-11-o2', 'mission-be-messaging-mastery-11', 2, 'Scenario: audit trail of every admin action', 'Choose the correct tool for a long-retention, replayable, multi-service event history.'),
  ('mission-be-messaging-mastery-11-o3', 'mission-be-messaging-mastery-11', 3, 'Scenario: real-time typing indicator in a chat app', 'Choose the correct tool for a channel that must carry data in both directions in real time.'),
  ('mission-be-messaging-mastery-12-o1', 'mission-be-messaging-mastery-12', 1, 'Scenario Alpha: refund processing', 'Judge which system is correct for ordered, retry-safe, exactly-once steps -- and why the other three fail.'),
  ('mission-be-messaging-mastery-12-o2', 'mission-be-messaging-mastery-12', 2, 'Scenario Bravo: clickstream analytics', 'Judge which system is correct for high-throughput, multi-team, replayable event capture -- and why the other three fail.'),
  ('mission-be-messaging-mastery-12-o3', 'mission-be-messaging-mastery-12', 3, 'Scenario Charlie: live sports score ticker', 'Judge which system is correct for one-way, high-fanout, real-time delivery to a browser -- and why the other three fail.'),
  ('mission-be-messaging-mastery-12-o4', 'mission-be-messaging-mastery-12', 4, 'Write the decision page', 'Synthesize the judgment calls from all three scenarios into the rule leadership actually asked for.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be-messaging-mastery-01-o1-c1', 'mission-be-messaging-mastery-01-o1', 1, 'multiple_choice', 'BullMQ has no storage engine of its own -- every job, delay and lock lives inside Redis data structures. Why does that actually make BullMQ''s guarantees possible?', '{"question":"BullMQ has no storage engine of its own -- every job, delay and lock lives inside Redis data structures. Why does that actually make BullMQ''s guarantees possible?","options":[{"id":"a","text":"Redis is faster than a dedicated broker, so BullMQ is faster too"},{"id":"b","text":"Redis''s single-threaded command execution and atomic operations let BullMQ move a job between states -- waiting, active, completed -- as one indivisible step, with nothing else able to observe it half-moved"},{"id":"c","text":"Redis persists to disk by default, so no configuration is ever required"},{"id":"d","text":"Redis clusters automatically shard jobs across workers"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-messaging-mastery-01-o2-c1', 'mission-be-messaging-mastery-01-o2', 1, 'drag_and_drop', 'Match each BullMQ class to the role it actually plays.', '{"items":[{"id":"p1","text":"Queue"},{"id":"p2","text":"Worker"},{"id":"p3","text":"QueueEvents"},{"id":"p4","text":"Job"}],"targets":[{"id":"t1","label":"Adds jobs and manages the queue''s data in Redis; does not process anything itself"},{"id":"t2","label":"Pulls jobs off the queue and actually executes the processor function"},{"id":"t3","label":"Subscribes to Redis pub/sub for job lifecycle events (completed, failed, progress) without participating in processing"},{"id":"t4","label":"Represents one unit of work, its data, its state, and its attempt history"}]}'::jsonb, '{"correctMapping":{"p1":"t1","p2":"t2","p3":"t3","p4":"t4"}}'::jsonb),

  ('mission-be-messaging-mastery-02-o1-c1', 'mission-be-messaging-mastery-02-o1', 1, 'drag_and_drop', 'Match each BullMQ reliability feature to the problem it actually solves.', '{"items":[{"id":"f1","text":"Delayed jobs"},{"id":"f2","text":"Repeatable jobs"},{"id":"f3","text":"Retries with backoff"},{"id":"f4","text":"Concurrency"},{"id":"f5","text":"Rate limiting"},{"id":"f6","text":"Flows (parent/child jobs)"}],"targets":[{"id":"t1","label":"Runs a job at a specific future time instead of immediately"},{"id":"t2","label":"Runs a job on a recurring schedule without an external cron process"},{"id":"t3","label":"Re-attempts a failed job with growing delay between attempts instead of hammering immediately"},{"id":"t4","label":"Controls how many jobs a single worker processes in parallel"},{"id":"t5","label":"Caps how many jobs a queue releases in a given time window, regardless of how many workers are available"},{"id":"t6","label":"Makes a parent job wait until all of its child jobs finish before it''s allowed to run"}]}'::jsonb, '{"correctMapping":{"f1":"t1","f2":"t2","f3":"t3","f4":"t4","f5":"t5","f6":"t6"}}'::jsonb),
  ('mission-be-messaging-mastery-02-o2-c1', 'mission-be-messaging-mastery-02-o2', 1, 'code_debugging', 'This job retries up to 5 times on failure, but a downstream outage gets hammered by all 5 attempts within the same second. Which line guarantees that?', '{"language":"javascript","code":"await emailQueue.add(\"welcome\", payload, {\n  attempts: 5,\n  backoff: { type: \"fixed\", delay: 0 },\n});","question":"This job retries up to 5 times on failure, but a downstream outage gets hammered by all 5 attempts within the same second. Which line guarantees that?"}'::jsonb, '{"requiredLineIds":["  backoff: { type: \"fixed\", delay: 0 },"]}'::jsonb),

  ('mission-be-messaging-mastery-03-o1-c1', 'mission-be-messaging-mastery-03-o1', 1, 'drag_and_drop', 'Match each RabbitMQ exchange type to how it actually routes messages.', '{"items":[{"id":"e1","text":"Direct exchange"},{"id":"e2","text":"Topic exchange"},{"id":"e3","text":"Fanout exchange"},{"id":"e4","text":"Headers exchange"}],"targets":[{"id":"t1","label":"Routes a message to any queue bound with a routing key that exactly matches the message''s routing key"},{"id":"t2","label":"Routes using wildcard patterns against the routing key (* for one word, # for zero or more)"},{"id":"t3","label":"Ignores the routing key entirely and broadcasts to every bound queue"},{"id":"t4","label":"Routes based on matching message header attributes instead of the routing key at all"}]}'::jsonb, '{"correctMapping":{"e1":"t1","e2":"t2","e3":"t3","e4":"t4"}}'::jsonb),
  ('mission-be-messaging-mastery-03-o2-c1', 'mission-be-messaging-mastery-03-o2', 1, 'investigation', 'The message publish succeeds and the broker never logs an error, yet the us-fulfillment queue never receives it. Which evidence explains why?', '{"evidence":[{"id":"ev1","label":"Exchange config","detail":"orders.topic exchange (type: topic) receives a message published with routing key orders.us.created."},{"id":"ev2","label":"Binding","detail":"The us-fulfillment queue is bound to orders.topic with binding key orders.eu.*."},{"id":"ev3","label":"Publish confirm","detail":"The broker returns a successful publisher confirm for the message -- the exchange accepted it without error."}],"question":"The message publish succeeds and the broker never logs an error, yet the us-fulfillment queue never receives it. Which evidence explains why?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-messaging-mastery-04-o1-c1', 'mission-be-messaging-mastery-04-o1', 1, 'code_debugging', 'A consumer crashes mid-payout and the message is simply gone -- RabbitMQ never redelivers it to anyone. Which line causes that?', '{"language":"javascript","code":"channel.consume(\"payouts\", (msg) => {\n  processPayout(JSON.parse(msg.content.toString()));\n}, { noAck: true });","question":"A consumer crashes mid-payout and the message is simply gone -- RabbitMQ never redelivers it to anyone. Which line causes that?"}'::jsonb, '{"requiredLineIds":["}, { noAck: true });"]}'::jsonb),
  ('mission-be-messaging-mastery-04-o2-c1', 'mission-be-messaging-mastery-04-o2', 1, 'multiple_choice', 'A payout message keeps failing validation and RabbitMQ keeps redelivering it to the same consumer forever, blocking every message behind it. What actually fixes this?', '{"question":"A payout message keeps failing validation and RabbitMQ keeps redelivering it to the same consumer forever, blocking every message behind it. What actually fixes this?","options":[{"id":"a","text":"Increase prefetch so the consumer can skip past it"},{"id":"b","text":"Configure a dead-letter exchange (DLX) on the queue with a max-retry policy, so a message that keeps failing gets routed off to a separate queue instead of redelivered indefinitely"},{"id":"c","text":"Switch the exchange type to fanout"},{"id":"d","text":"Enable publisher confirms on the producer"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-messaging-mastery-05-o1-c1', 'mission-be-messaging-mastery-05-o1', 1, 'drag_and_drop', 'Match each Kafka replication concept to what it actually does.', '{"items":[{"id":"r1","text":"Leader replica"},{"id":"r2","text":"Follower replica"},{"id":"r3","text":"In-sync replica set (ISR)"},{"id":"r4","text":"Replication factor"}],"targets":[{"id":"t1","label":"Handles every read and write for a partition; the single source of truth"},{"id":"t2","label":"Replicates the leader''s log passively; only takes over if the leader fails"},{"id":"t3","label":"The set of replicas -- leader plus followers -- caught up closely enough to count toward durability; a lagging follower gets dropped from it"},{"id":"t4","label":"The number of copies of a partition Kafka maintains across the cluster, set per topic"}]}'::jsonb, '{"correctMapping":{"r1":"t1","r2":"t2","r3":"t3","r4":"t4"}}'::jsonb),
  ('mission-be-messaging-mastery-05-o2-c1', 'mission-be-messaging-mastery-05-o2', 1, 'investigation', 'Replication factor is 3, and all three brokers are online, yet the team is being warned this partition is one leader failure away from data loss. Which evidence explains that?', '{"evidence":[{"id":"ev1","label":"Topic config","detail":"orders-events topic, replication-factor=3."},{"id":"ev2","label":"ISR status","detail":"Partition 2''s ISR currently contains only the leader -- both followers have fallen out of sync and been dropped."},{"id":"ev3","label":"Cluster health","detail":"All 3 brokers hosting this topic are online and reachable."}],"question":"Replication factor is 3, and all three brokers are online, yet the team is being warned this partition is one leader failure away from data loss. Which evidence explains that?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-messaging-mastery-06-o1-c1', 'mission-be-messaging-mastery-06-o1', 1, 'drag_and_drop', 'Match each partition assignment strategy to how it actually behaves during a rebalance.', '{"items":[{"id":"s1","text":"Range"},{"id":"s2","text":"Round-robin"},{"id":"s3","text":"Sticky"},{"id":"s4","text":"Cooperative-sticky"}],"targets":[{"id":"t1","label":"Assigns each consumer a contiguous range of partitions per topic; can load-balance unevenly across topics"},{"id":"t2","label":"Spreads all partitions across all consumers one at a time, topic by topic, usually more even than range"},{"id":"t3","label":"Tries to preserve each consumer''s existing assignment across a rebalance to minimize reshuffling, but still revokes everything first"},{"id":"t4","label":"Preserves existing assignments and only revokes the specific partitions that actually need to move, instead of stopping every consumer"}]}'::jsonb, '{"correctMapping":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4"}}'::jsonb),
  ('mission-be-messaging-mastery-06-o2-c1', 'mission-be-messaging-mastery-06-o2', 1, 'investigation', 'One consumer restarting caused the entire group of 12 to stop processing, not just the partitions that actually moved. Which evidence explains why?', '{"evidence":[{"id":"ev1","label":"Consumer group protocol","detail":"The group is configured with the default eager rebalance protocol."},{"id":"ev2","label":"Incident","detail":"A single consumer restart caused all 12 consumers in the group to stop processing for several seconds, not just the one that changed."},{"id":"ev3","label":"Partition count","detail":"The topic has 12 partitions, evenly assigned before the restart."}],"question":"One consumer restarting caused the entire group of 12 to stop processing, not just the partitions that actually moved. Which evidence explains why?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be-messaging-mastery-07-o1-c1', 'mission-be-messaging-mastery-07-o1', 1, 'drag_and_drop', 'Match each Kafka mechanism to the guarantee it actually provides.', '{"items":[{"id":"m1","text":"Time/size-based retention"},{"id":"m2","text":"Log compaction"},{"id":"m3","text":"Idempotent producer"},{"id":"m4","text":"Transactions"}],"targets":[{"id":"t1","label":"Deletes entire log segments once they cross an age or size limit, regardless of key"},{"id":"t2","label":"Keeps only the latest value written for each key, forever, deleting older values for that same key"},{"id":"t3","label":"Prevents a single producer''s network retry from writing the same message twice, using a producer id and sequence number"},{"id":"t4","label":"Lets a producer write to multiple partitions atomically, so a consumer using read-committed never sees a partial write"}]}'::jsonb, '{"correctMapping":{"m1":"t1","m2":"t2","m3":"t3","m4":"t4"}}'::jsonb),
  ('mission-be-messaging-mastery-07-o2-c1', 'mission-be-messaging-mastery-07-o2', 1, 'investigation', 'A brand-new consumer reading a compacted topic from the beginning expected the full update history and got only the latest value per key. Which evidence explains that gap?', '{"evidence":[{"id":"ev1","label":"Topic config","detail":"user-profile-updates topic has cleanup.policy=compact."},{"id":"ev2","label":"Consumer expectation","detail":"A new consumer assumed reading from the beginning would replay every historical update event, in order, the way it would for a retention-only topic."},{"id":"ev3","label":"Actual read result","detail":"The new consumer only receives one event per user id -- the latest one -- not the full history of updates."}],"question":"A brand-new consumer reading a compacted topic from the beginning expected the full update history and got only the latest value per key. Which evidence explains that gap?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be-messaging-mastery-08-o1-c1', 'mission-be-messaging-mastery-08-o1', 1, 'drag_and_drop', 'Match each Kafka ecosystem tool to the problem it actually solves.', '{"items":[{"id":"c1","text":"Schema Registry"},{"id":"c2","text":"Kafka Connect"},{"id":"c3","text":"Stream processing (Kafka Streams / ksqlDB)"}],"targets":[{"id":"t1","label":"Enforces and versions a schema for every topic, blocking a producer from publishing a payload that breaks compatibility with existing consumers"},{"id":"t2","label":"Moves data in and out of Kafka from external systems (databases, S3, search indexes) using pre-built connectors instead of custom producer/consumer code"},{"id":"t3","label":"Computes continuously over the log itself -- joins, aggregations, windowing -- instead of just storing and forwarding it"}]}'::jsonb, '{"correctMapping":{"c1":"t1","c2":"t2","c3":"t3"}}'::jsonb),
  ('mission-be-messaging-mastery-08-o2-c1', 'mission-be-messaging-mastery-08-o2', 1, 'investigation', 'The producer''s deploy failed at the schema-registration step, before a single message ever reached the topic. Which evidence explains why the registry blocked it?', '{"evidence":[{"id":"ev1","label":"Compatibility mode","detail":"Schema Registry compatibility mode is set to BACKWARD for the orders-v1 subject."},{"id":"ev2","label":"Change made","detail":"A producer deployed a new schema version that removed a field several existing consumers still read directly, without a default."},{"id":"ev3","label":"Registry response","detail":"The registration request for the new schema version was rejected outright."}],"question":"The producer''s deploy failed at the schema-registration step, before a single message ever reached the topic. Which evidence explains why the registry blocked it?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-messaging-mastery-09-o1-c1', 'mission-be-messaging-mastery-09-o1', 1, 'multiple_choice', 'A user submits a checkout form and needs to see "Order placed" immediately. A confirmation email should go out within the next few seconds, but the checkout response must not wait for the email provider to answer. Which tool is actually correct?', '{"question":"A user submits a checkout form and needs to see \"Order placed\" immediately. A confirmation email should go out within the next few seconds, but the checkout response must not wait for the email provider to answer. Which tool is actually correct?","options":[{"id":"a","text":"A synchronous API call to the email provider, made inline before responding to the user"},{"id":"b","text":"BullMQ: enqueue an email job and return the checkout response immediately -- the job runs asynchronously, with retries if the provider is briefly down"},{"id":"c","text":"A plain database job table polled by a cron script every 10 minutes"},{"id":"d","text":"None of these -- email should never be automated"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-messaging-mastery-09-o2-c1', 'mission-be-messaging-mastery-09-o2', 1, 'multiple_choice', 'A finance report needs to regenerate once a night, has no user waiting on it, must not run twice if a process restarts mid-run, and the team has a lightly-loaded Postgres instance but no Redis anywhere in the stack. Which tool is actually correct?', '{"question":"A finance report needs to regenerate once a night, has no user waiting on it, must not run twice if a process restarts mid-run, and the team has a lightly-loaded Postgres instance but no Redis anywhere in the stack. Which tool is actually correct?","options":[{"id":"a","text":"A synchronous API endpoint triggered by a manual click each night"},{"id":"b","text":"BullMQ, since delayed and repeatable jobs are its specialty"},{"id":"c","text":"A plain database job table: a row per run, a status column, and a lock/claim query -- no new infrastructure, and the once-a-night frequency doesn''t need Redis-grade throughput"},{"id":"d","text":"Send it over WebSocket to whichever admin is online"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-be-messaging-mastery-10-o1-c1', 'mission-be-messaging-mastery-10-o1', 1, 'multiple_choice', 'Every "order placed" event needs to reach five independent services, each processing it at its own pace, and a new sixth service should be able to start consuming the same events without anyone touching the producer. Which tool is actually correct?', '{"question":"Every \"order placed\" event needs to reach five independent services, each processing it at its own pace, and a new sixth service should be able to start consuming the same events without anyone touching the producer. Which tool is actually correct?","options":[{"id":"a","text":"RabbitMQ with a single queue shared by all five services"},{"id":"b","text":"Kafka: publish once to a topic, and any number of independent consumer groups -- including a future sixth one -- can read the full event history at their own pace without the producer knowing or caring"},{"id":"c","text":"A synchronous API call to all five services in sequence"},{"id":"d","text":"SSE from the order service directly to each of the five"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-messaging-mastery-10-o2-c1', 'mission-be-messaging-mastery-10-o2', 1, 'multiple_choice', 'A dispatcher''s dashboard needs a driver''s location updated on screen within a second of it changing, one-way from server to browser, for potentially thousands of dashboards open at once, with no need for the browser to ever send anything back on that channel. Which tool is actually correct?', '{"question":"A dispatcher''s dashboard needs a driver''s location updated on screen within a second of it changing, one-way from server to browser, for potentially thousands of dashboards open at once, with no need for the browser to ever send anything back on that channel. Which tool is actually correct?","options":[{"id":"a","text":"WebSocket, since it''s bidirectional and therefore the most powerful option"},{"id":"b","text":"Kafka, consumed directly by the browser"},{"id":"c","text":"SSE (Server-Sent Events): a plain HTTP connection the server pushes updates over, which is exactly a one-way, server-to-client stream and scales more simply than a full bidirectional protocol nobody needs here"},{"id":"d","text":"RabbitMQ, with the browser as a direct AMQP consumer"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-be-messaging-mastery-11-o1-c1', 'mission-be-messaging-mastery-11-o1', 1, 'multiple_choice', 'A user requests a password reset. The reset email must be sent, but the API response confirming "check your email" can''t wait on the email provider. Which tool?', '{"question":"A user requests a password reset. The reset email must be sent, but the API response confirming \"check your email\" can''t wait on the email provider. Which tool?","options":[{"id":"a","text":"A synchronous API call to the email provider, made inline before responding"},{"id":"b","text":"BullMQ -- queue the email send, return the API response immediately"},{"id":"c","text":"A dedicated Kafka topic just for this one email type"},{"id":"d","text":"A database table polled once an hour"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-messaging-mastery-11-o2-c1', 'mission-be-messaging-mastery-11-o2', 1, 'multiple_choice', 'Every admin action across a dozen services needs to be captured, kept for a year, and made replayable for a future compliance tool that doesn''t exist yet. Which tool?', '{"question":"Every admin action across a dozen services needs to be captured, kept for a year, and made replayable for a future compliance tool that doesn''t exist yet. Which tool?","options":[{"id":"a","text":"RabbitMQ, consumed once and discarded"},{"id":"b","text":"Kafka, with a year-long retention window, since nothing here should be delivered once and forgotten"},{"id":"c","text":"BullMQ, since jobs sound like actions"},{"id":"d","text":"A plain database job table"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-messaging-mastery-11-o3-c1', 'mission-be-messaging-mastery-11-o3', 1, 'multiple_choice', 'A chat app needs to show "so-and-so is typing..." the instant a user starts typing, and the browser also needs to send that keystroke event back to the server. Which tool?', '{"question":"A chat app needs to show \"so-and-so is typing...\" the instant a user starts typing, and the browser also needs to send that keystroke event back to the server. Which tool?","options":[{"id":"a","text":"SSE, since it''s simpler than the alternatives"},{"id":"b","text":"WebSocket, since the browser needs to send events back to the server as well as receive them"},{"id":"c","text":"Kafka, consumed and produced directly by the browser"},{"id":"d","text":"A plain synchronous API call on every keystroke"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-messaging-mastery-12-o1-c1', 'mission-be-messaging-mastery-12-o1', 1, 'multiple_choice', 'Scenario Alpha: a refund needs to debit a payment provider, update three internal ledgers, and notify the customer. It must happen exactly once, ordering across the three ledger updates matters, and a partial failure has to be retried without double-charging anyone. Which system is actually correct?', '{"question":"Scenario Alpha: a refund needs to debit a payment provider, update three internal ledgers, and notify the customer. It must happen exactly once, ordering across the three ledger updates matters, and a partial failure has to be retried without double-charging anyone. Which system is actually correct?","options":[{"id":"a","text":"A synchronous API call chaining all four steps inline -- fails because a timeout partway through leaves the operation in an unknown state with no record of what completed"},{"id":"b","text":"BullMQ with a flow: a parent refund job and child jobs per ledger update, using job ids for idempotency -- correct, because flows give ordered, trackable, retry-safe steps with built-in persistence in Redis"},{"id":"c","text":"RabbitMQ, fire-and-forget to four independent queues -- fails because nothing coordinates the four steps or guarantees they complete as one unit"},{"id":"d","text":"Kafka, one event per step -- fails because Kafka has no built-in notion of \"these four steps belong to one job that must fully complete,\" which is exactly what this needs"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-messaging-mastery-12-o2-c1', 'mission-be-messaging-mastery-12-o2', 1, 'multiple_choice', 'Scenario Bravo: every click across the whole product needs to be captured at tens of thousands of events per second, with multiple independent teams consuming the same stream for different purposes, and 30-day replay must be possible. Which system is actually correct?', '{"question":"Scenario Bravo: every click across the whole product needs to be captured at tens of thousands of events per second, with multiple independent teams consuming the same stream for different purposes, and 30-day replay must be possible. Which system is actually correct?","options":[{"id":"a","text":"BullMQ -- fails because Redis-backed queues aren''t built for this throughput or for multiple independent teams replaying the same history"},{"id":"b","text":"RabbitMQ -- fails because a consumed message is gone; there is no 30-day replay story without bolting on extra storage"},{"id":"c","text":"Kafka: high-throughput partitioned log, independent consumer groups per team, retention set to 30 days -- correct, this is exactly the shape Kafka is built for"},{"id":"d","text":"A synchronous API call per click -- fails outright at this volume and adds latency to every single click"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be-messaging-mastery-12-o3-c1', 'mission-be-messaging-mastery-12-o3', 1, 'multiple_choice', 'Scenario Charlie: a live score needs to reach every open browser tab watching a match within a second of changing, one-way from server to client, for up to fifty thousand simultaneous viewers, with no need for the browser to send anything back. Which system is actually correct?', '{"question":"Scenario Charlie: a live score needs to reach every open browser tab watching a match within a second of changing, one-way from server to client, for up to fifty thousand simultaneous viewers, with no need for the browser to send anything back. Which system is actually correct?","options":[{"id":"a","text":"WebSocket -- technically works, but pays for full bidirectional plumbing and connection state this use case never needs, for no benefit"},{"id":"b","text":"SSE: a plain HTTP push connection built exactly for one-way server-to-client updates, scales simply behind normal HTTP infrastructure -- correct for this case"},{"id":"c","text":"Kafka, consumed directly from the browser -- fails because Kafka''s protocol and client model were never built for untrusted, high-churn browser connections"},{"id":"d","text":"RabbitMQ, with each browser as a direct AMQP consumer -- fails for the same reason: browsers were never meant to hold an AMQP connection at that scale"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-messaging-mastery-12-o4-c1', 'mission-be-messaging-mastery-12-o4', 1, 'boss_encounter', 'Having judged Alpha, Bravo and Charlie, state the actual rule behind all twenty scenarios.', '{"stages":[{"objectiveRef":"mission-be-messaging-mastery-12-o1","label":"Scenario Alpha: refund processing"},{"objectiveRef":"mission-be-messaging-mastery-12-o2","label":"Scenario Bravo: clickstream analytics"},{"objectiveRef":"mission-be-messaging-mastery-12-o3","label":"Scenario Charlie: live sports score ticker"}],"task":"Having judged Alpha, Bravo and Charlie, state the actual rule behind all twenty scenarios, not just these three: match the tool to what the work actually needs -- ordered, retry-safe, exactly-once steps go to BullMQ; high-throughput, replayable, multi-consumer streams go to Kafka; routing-heavy fan-out with per-consumer acknowledgement goes to RabbitMQ; and one-way real-time delivery to a browser goes to SSE, reserving WebSocket only for when the browser genuinely needs to send data back on the same channel. Familiarity is never one of the criteria."}'::jsonb, '{"requiredObjectiveIds":["mission-be-messaging-mastery-12-o1","mission-be-messaging-mastery-12-o2","mission-be-messaging-mastery-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be-messaging-mastery-01-o1-c1', 'orientation', 'Every job transition -- waiting to active, active to completed -- has to be atomic, or two workers could grab the same job. What does Redis give BullMQ that makes that possible?', 18, 1),
  ('mission-be-messaging-mastery-01-o1-c1', 'solution', 'b: Redis''s atomic commands let BullMQ move a job between states as a single indivisible operation, which is the actual guarantee, not raw speed or clustering.', 30, 2),
  ('mission-be-messaging-mastery-01-o2-c1', 'orientation', 'One of these four classes processes nothing at all -- it only watches. Another only ever writes, never runs a processor function.', 18, 1),
  ('mission-be-messaging-mastery-01-o2-c1', 'solution', 'Queue adds/manages jobs, Worker actually processes them, QueueEvents only listens for lifecycle events, Job is the unit of work itself.', 30, 2),

  ('mission-be-messaging-mastery-02-o1-c1', 'orientation', 'Split these six into "when it runs," "how often it runs," and "how much runs at once" -- each feature answers exactly one of those questions.', 18, 1),
  ('mission-be-messaging-mastery-02-o1-c1', 'solution', 'Delayed = future time, repeatable = recurring schedule, retries with backoff = growing delay between re-attempts, concurrency = parallelism per worker, rate limiting = a hard cap on release speed, flows = parent waits on children.', 30, 2),
  ('mission-be-messaging-mastery-02-o2-c1', 'orientation', 'Five attempts with zero delay between them is the same thing as five attempts with no backoff at all.', 18, 1),
  ('mission-be-messaging-mastery-02-o2-c1', 'solution', 'backoff: { type: "fixed", delay: 0 } sets the wait between retries to zero, so all 5 attempts fire back-to-back into the same outage instead of spacing out.', 30, 2),

  ('mission-be-messaging-mastery-03-o1-c1', 'orientation', 'Two of these four route on the key. One ignores the key completely. One doesn''t use the key at all, using something else instead.', 18, 1),
  ('mission-be-messaging-mastery-03-o1-c1', 'solution', 'Direct = exact key match, topic = wildcard pattern match, fanout = broadcast regardless of key, headers = match on header attributes instead of the key.', 30, 2),
  ('mission-be-messaging-mastery-03-o2-c1', 'orientation', 'A successful publish only proves the exchange accepted the message -- it says nothing about whether any queue''s binding actually matched it.', 18, 1),
  ('mission-be-messaging-mastery-03-o2-c1', 'solution', 'ev2: the queue is bound with orders.eu.*, but the message was published with orders.us.created -- the pattern never matches, so the topic exchange has nowhere to route it.', 30, 2),

  ('mission-be-messaging-mastery-04-o1-c1', 'orientation', 'This flag tells RabbitMQ to consider the message handled the instant it''s delivered, not the instant it''s actually processed.', 18, 1),
  ('mission-be-messaging-mastery-04-o1-c1', 'solution', 'noAck: true means the broker marks the message acknowledged on delivery, before processPayout even runs -- a crash mid-processing loses it with nothing left to redeliver.', 30, 2),
  ('mission-be-messaging-mastery-04-o2-c1', 'orientation', 'The fix needs somewhere for a permanently-failing message to go that isn''t "back to the front of the same queue."', 18, 1),
  ('mission-be-messaging-mastery-04-o2-c1', 'solution', 'b: a dead-letter exchange with a max-retry policy routes a message that keeps failing off to its own queue, instead of redelivering it to the same consumer forever.', 30, 2),

  ('mission-be-messaging-mastery-05-o1-c1', 'orientation', 'One of these four is a count, one is a set, and two are roles a single replica can hold.', 18, 1),
  ('mission-be-messaging-mastery-05-o1-c1', 'solution', 'Leader handles reads/writes, follower replicates passively, ISR is the set of replicas caught up enough to count toward durability, replication factor is the total copy count.', 30, 2),
  ('mission-be-messaging-mastery-05-o2-c1', 'orientation', 'Replication factor 3 only guarantees three copies exist somewhere in the config. It says nothing about whether those copies are actually caught up right now.', 18, 1),
  ('mission-be-messaging-mastery-05-o2-c1', 'solution', 'ev2: both followers have already fallen out of the ISR, so only the leader''s copy is actually current -- lose it, and there is no caught-up replica left to promote.', 30, 2),

  ('mission-be-messaging-mastery-06-o1-c1', 'orientation', 'Three of these preserve nothing about the previous assignment. One tries to. Of the ones that try, only one avoids a full stop-the-world revoke.', 18, 1),
  ('mission-be-messaging-mastery-06-o1-c1', 'solution', 'Range assigns contiguous per-topic ranges, round-robin spreads evenly, sticky preserves assignment but still revokes everything first, cooperative-sticky only revokes what actually needs to move.', 30, 2),
  ('mission-be-messaging-mastery-06-o2-c1', 'orientation', 'The partition count and the specific incident both describe what happened. One entry describes the protocol setting that made it happen that way.', 18, 1),
  ('mission-be-messaging-mastery-06-o2-c1', 'solution', 'ev1: the eager rebalance protocol revokes every partition from every consumer in the group before reassigning any of them, so a single membership change stops the whole group, not just the partitions that moved.', 30, 2),

  ('mission-be-messaging-mastery-07-o1-c1', 'orientation', 'Two of these decide when data disappears. Two decide how exactly-once actually gets delivered on top of Kafka''s normal at-least-once behavior.', 18, 1),
  ('mission-be-messaging-mastery-07-o1-c1', 'solution', 'Retention deletes by age/size regardless of key, compaction keeps only the latest value per key, idempotent producer stops duplicate writes from retries, transactions make multi-partition writes atomic.', 30, 2),
  ('mission-be-messaging-mastery-07-o2-c1', 'orientation', 'The consumer''s expectation was reasonable for a normal topic. Check what kind of topic this actually is.', 18, 1),
  ('mission-be-messaging-mastery-07-o2-c1', 'solution', 'ev1: cleanup.policy=compact means old values for the same key are deleted as newer ones arrive -- there was never a full history left to replay, by design.', 30, 2),

  ('mission-be-messaging-mastery-08-o1-c1', 'orientation', 'One of these three tools prevents a bad write. One moves data across a system boundary. One computes over data that''s already there.', 18, 1),
  ('mission-be-messaging-mastery-08-o1-c1', 'solution', 'Schema Registry enforces compatibility on write, Kafka Connect bridges external systems without custom code, stream processing computes continuously over the log.', 30, 2),
  ('mission-be-messaging-mastery-08-o2-c1', 'orientation', 'BACKWARD compatibility is a promise about what a new schema is allowed to do to consumers still running the old one.', 18, 1),
  ('mission-be-messaging-mastery-08-o2-c1', 'solution', 'ev2: removing a field that existing consumers still read directly, without a default, breaks backward compatibility -- the registry rejects the registration before any message can carry the broken shape.', 30, 2),

  ('mission-be-messaging-mastery-09-o1-c1', 'orientation', 'Rule out the option that blocks the response, then rule out the one whose delay is measured in minutes, not seconds.', 18, 1),
  ('mission-be-messaging-mastery-09-o1-c1', 'solution', 'b: BullMQ lets the checkout response return immediately while the email job runs asynchronously with retries -- sync blocks on the provider, and a 10-minute poll is far too slow for "within seconds."', 30, 2),
  ('mission-be-messaging-mastery-09-o2-c1', 'orientation', 'Two constraints matter here: no Redis in the stack, and the frequency is once a night, not once a second.', 18, 1),
  ('mission-be-messaging-mastery-09-o2-c1', 'solution', 'c: a plain database job table needs no new infrastructure and easily handles once-a-night throughput with a simple claim query -- BullMQ would require standing up Redis for no real benefit at this frequency.', 30, 2),

  ('mission-be-messaging-mastery-10-o1-c1', 'orientation', 'The requirement that should jump out: a future, unknown consumer needs to read the full history independently. Which system treats "consumer" as replayable and decoupled from the producer by default?', 18, 1),
  ('mission-be-messaging-mastery-10-o1-c1', 'solution', 'b: Kafka''s topic-plus-consumer-groups model lets any number of independent groups, including future ones, read the same retained history without the producer ever needing to know they exist.', 30, 2),
  ('mission-be-messaging-mastery-10-o2-c1', 'orientation', 'The browser never needs to send anything back on this channel -- that rules out the option built specifically for two-way traffic.', 18, 1),
  ('mission-be-messaging-mastery-10-o2-c1', 'solution', 'c: SSE is a one-way, server-to-client HTTP push built for exactly this, and it scales more simply than a bidirectional protocol this use case has no need for.', 30, 2),

  ('mission-be-messaging-mastery-11-o1-c1', 'orientation', 'Same shape as the checkout email from an earlier mission -- non-blocking, near-immediate, no new stream needed.', 18, 1),
  ('mission-be-messaging-mastery-11-o1-c1', 'solution', 'b: BullMQ queues the email send and lets the API respond immediately, with retries handling a briefly-down provider.', 30, 2),
  ('mission-be-messaging-mastery-11-o2-c1', 'orientation', 'Long retention, replay, and multiple independent readers across services -- that combination points at one system specifically.', 18, 1),
  ('mission-be-messaging-mastery-11-o2-c1', 'solution', 'b: Kafka with year-long retention is built for exactly this -- a durable, replayable, multi-consumer event history, not a queue that forgets on delivery.', 30, 2),
  ('mission-be-messaging-mastery-11-o3-c1', 'orientation', 'The browser has to send data on this same channel, not just receive it -- that''s the deciding requirement.', 18, 1),
  ('mission-be-messaging-mastery-11-o3-c1', 'solution', 'b: WebSocket is the one option built for genuine two-way traffic between browser and server on a single connection.', 30, 2),

  ('mission-be-messaging-mastery-12-o1-c1', 'orientation', 'Look for the option that gives you ordering, retry-safety, and a way to know exactly which steps of a multi-step job already completed.', 20, 1),
  ('mission-be-messaging-mastery-12-o1-c1', 'solution', 'b: BullMQ flows track a parent job and its children with persistence and idempotency built in, which is exactly what a multi-step, exactly-once financial operation needs -- none of the other three coordinate multi-step completion at all.', 35, 2),
  ('mission-be-messaging-mastery-12-o2-c1', 'orientation', 'Volume, multiple independent consumers, and a 30-day replay requirement together point at one system''s core design.', 20, 1),
  ('mission-be-messaging-mastery-12-o2-c1', 'solution', 'c: Kafka''s partitioned, retained log is built precisely for high-throughput capture with independent, replayable consumer groups -- the other three either can''t sustain the throughput or can''t replay history at all.', 35, 2),
  ('mission-be-messaging-mastery-12-o3-c1', 'orientation', 'The browser never talks back on this channel -- that rules out the option built specifically for two-way traffic, even though it would technically still work.', 20, 1),
  ('mission-be-messaging-mastery-12-o3-c1', 'solution', 'b: SSE is a one-way HTTP push built exactly for this fanout shape; WebSocket would work but pays for unneeded bidirectional plumbing, and Kafka/RabbitMQ were never built for untrusted browser-scale client connections.', 35, 2),
  ('mission-be-messaging-mastery-12-o4-c1', 'orientation', 'Look at what all three judgments had in common as a method -- what property of the work each correct answer was actually chosen for, not the tool name itself.', 20, 1),
  ('mission-be-messaging-mastery-12-o4-c1', 'solution', 'Match the tool to the work''s actual shape: coordinated exactly-once steps to BullMQ, high-throughput replayable streams to Kafka, routing-heavy acknowledged fan-out to RabbitMQ, and one-way real-time browser delivery to SSE, with WebSocket reserved for genuine two-way channels. Never pick by familiarity.', 32, 2);
